import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.DDEX3mHW.js";const u=JSON.parse('{"title":"搭建节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodes.md","filePath":"guide/nodes.md","lastUpdated":1792241433000}'),o={name:"guide/nodes.md"};function l(i,t,n,s,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="搭建节点" tabindex="-1">搭建节点 <a class="header-anchor" href="#搭建节点" aria-label="Permalink to &quot;搭建节点&quot;">​</a></h1><p>在落地机上部署代理节点（入站）。所有配置由面板生成，节点上的 agent 只负责下载内核、写入配置、运行和守护进程。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>落地机已按 <a href="./install">安装部署</a> 装好节点 agent，并在面板里显示在线</li><li>Linux amd64 / arm64，root 权限</li><li>建议安装 nftables（<code>apt install nftables</code>）：入站流量统计、白名单和 Hysteria2 端口跳跃依赖它；没有 nftables 时节点照常工作，只是没有这些功能</li></ul><h2 id="安装内核" tabindex="-1">安装内核 <a class="header-anchor" href="#安装内核" aria-label="Permalink to &quot;安装内核&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>内核</strong> 标签 → <strong>安装内核</strong> → 选择节点和内核。</p><table tabindex="0"><thead><tr><th>内核</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Xray</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用官方校验文件校验</td></tr><tr><td>sing-box</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用 Release 资产的 SHA256 校验</td></tr><tr><td>Snell</td><td>5.0.1 / 4.1.1</td><td>只从官方 <code>dl.nssurge.com</code> 下载，使用内置的校验值</td></tr></tbody></table><p>一台节点可以同时安装多个内核，内核按节点分组显示。点击内核可以启停、重启、查看日志、更换版本或卸载；节点重启后内核会自动恢复运行。</p><h2 id="新建入站" tabindex="-1">新建入站 <a class="header-anchor" href="#新建入站" aria-label="Permalink to &quot;新建入站&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选择节点和内核 → 点击一个快速模板 → 填名称 → <strong>创建并下发</strong>。</p><p>端口留空会随机分配，UUID、密码、密钥留空会自动生成。</p><table tabindex="0"><thead><tr><th>模板</th><th>内核</th><th>说明</th></tr></thead><tbody><tr><td>VLESS + Reality + Vision</td><td>Xray / sing-box</td><td>推荐，无需域名和证书</td></tr><tr><td>VLESS + XHTTP + Reality</td><td>Xray</td><td></td></tr><tr><td>Shadowsocks 2022</td><td>Xray / sing-box</td><td></td></tr><tr><td>Trojan + TLS（自签）</td><td>Xray / sing-box</td><td>需要填写域名</td></tr><tr><td>VMess + WS + TLS</td><td>Xray / sing-box</td><td>兼容老客户端</td></tr><tr><td>Hysteria2</td><td>sing-box</td><td>基于 QUIC，可选端口跳跃</td></tr><tr><td>TUIC v5</td><td>sing-box</td><td>基于 QUIC</td></tr><tr><td>AnyTLS</td><td>sing-box</td><td></td></tr><tr><td>SS2022 + ShadowTLS</td><td>sing-box</td><td>仅 TCP</td></tr><tr><td>NaïveProxy</td><td>sing-box</td><td>需要域名和真实证书</td></tr><tr><td>Snell / Snell + ShadowTLS</td><td>Snell</td><td>Surge 专用</td></tr></tbody></table><h3 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h3><p>TLS 类入站有三种证书来源：</p><ul><li><strong>自动生成自签证书</strong>：开箱即用，客户端需要允许不安全证书（分享链接已自动带上）</li><li><strong>使用节点上的证书文件</strong>：填写证书和私钥在节点上的绝对路径</li><li><strong>自动申请证书（ACME）</strong>：仅 sing-box，需要 sing-box 1.14 及以上 <ul><li>域名必须解析到该节点</li><li>HTTP 验证：节点 80 端口要能从公网访问</li><li>DNS 验证：支持 Cloudflare（API Token）和阿里云（AccessKey），不需要 80 端口</li><li>证书由 sing-box 自动续期</li></ul></li></ul><p>NaïveProxy 必须使用真实证书（ACME 或证书文件）。</p><h3 id="hysteria2-端口跳跃" tabindex="-1">Hysteria2 端口跳跃 <a class="header-anchor" href="#hysteria2-端口跳跃" aria-label="Permalink to &quot;Hysteria2 端口跳跃&quot;">​</a></h3><p>在 Hysteria2 入站里填写一段 UDP 端口，例如 <code>20000-30000</code>。节点会用 nftables 把这段端口转到入站端口，客户端在其中随机切换，缓解运营商对单个 UDP 端口的限速。</p><ul><li>范围不能包含入站端口本身，不能和其他入站、转发或节点的转发端口段重叠</li><li>只有直连地址带跳跃参数；经中转连接时只转发一个端口，不跳跃</li></ul><h3 id="监听地址" tabindex="-1">监听地址 <a class="header-anchor" href="#监听地址" aria-label="Permalink to &quot;监听地址&quot;">​</a></h3><p>默认监听 <code>::</code>（同时支持 IPv4 和 IPv6）。如果节点在内核启动参数里完全禁用了 IPv6（<code>ipv6.disable=1</code>），部分内核会绑定失败，此时在高级选项里把监听地址改为 <code>0.0.0.0</code>。</p><h3 id="分流" tabindex="-1">分流 <a class="header-anchor" href="#分流" aria-label="Permalink to &quot;分流&quot;">​</a></h3><p>服务器侧的分流和链式：客户端照常连本节点，由节点内核决定流量从哪里出去。想在客户端订阅里组合“中转 → 落地”，见 <a href="./subscription#链式代理">订阅的链式代理</a>。</p><p>点入站 → <strong>分流</strong>，有两部分：</p><ul><li><strong>默认出口</strong>：直连（从本节点出去），或选另一个入站（其他节点上的入站、导入的节点），流量再经它出去，网站看到的是它的 IP（链式代理）</li><li><strong>分流规则</strong>：按目标把一部分流量送到别处，从上到下匹配，先命中先生效，都不命中的走默认出口</li></ul><p>每条分流规则选分类或填自定义域名 / IP，再选去向：<strong>直连</strong>、<strong>阻断</strong> 或某个出站节点。</p><table tabindex="0"><thead><tr><th>分类</th><th>内容</th></tr></thead><tbody><tr><td>流媒体</td><td>Netflix、Disney+、YouTube、HBO、Prime Video、Spotify、TikTok</td></tr><tr><td>AI</td><td>ChatGPT、Claude、Gemini</td></tr><tr><td>常用</td><td>Google、Telegram</td></tr><tr><td>其他</td><td>广告、BT 下载、回国流量（中国大陆的域名和 IP）</td></tr></tbody></table><p>常见用法：</p><ul><li>只让 Netflix / ChatGPT 走有解锁 IP 的节点（例如导入的机场节点），其他流量照常直连</li><li>落地机阻断 BT 和回国流量，避免被投诉或滥用</li><li>A → B → C 多级：给 A 的入站选 B 作为默认出口，再给 B 的入站选 C；每个节点只连下一跳</li><li>自定义域名包含子域名，例如填 <code>example.com</code> 也匹配 <code>www.example.com</code></li></ul><p>注意事项：</p><ul><li>分类数据自动更新：Xray 用 v2fly 的 geosite / geoip 数据，节点每天检查一次，有新版本就下载、校验后替换并重启 Xray（启动失败会恢复原文件），内核日志里可以看到更新记录；sing-box 首次使用某个分类时下载规则集并缓存，之后每天更新。两者都经 <strong>网站配置</strong> 里的 GitHub 加速地址下载，落地机需要能访问</li><li>Xray 能连接 VLESS / VMess / Trojan / Shadowsocks（不含插件和 ShadowTLS）/ SOCKS5 / HTTP 出站节点；Hysteria2、TUIC、AnyTLS 等请用 sing-box 内核；Snell 内核不支持分流，也不能作为出站节点</li><li>出站节点是本面板的自签证书入站时，Xray 用证书指纹校验；导入的节点如果跳过了证书验证，Xray 无法连接（新版 Xray 已移除 <code>allowInsecure</code>），请改用 sing-box</li><li>开启了“获取真实客户端 IP”的入站只能经中转连接，不能作为出站节点；只监听本机的入站只能被同一节点上的入站选用</li><li>出站节点开启了白名单时，会自动放行经它出站的节点；规则之间形成循环（A 经 B、B 又经 A）时无法保存</li><li>被选作默认出口或分流去向的入站不能直接删除，需先解除；订阅源刷新时也会保留这些节点。出站节点如果随内核或节点一起被删除，原本经它出去的流量会被丢弃（不会改为直连），请重新选择</li><li>用户流量统计照常按用户计算</li><li>保存会重启节点内核，正在经这个节点连接的会断开一下重连。如果你正用这个节点打开面板，保存时连接会中断，面板会在节点恢复后自动确认是否已保存</li><li>新配置让内核启动失败时（例如下载分流规则集失败），节点会自动恢复上一次能运行的配置并显示错误，不会因此掉线</li></ul><h2 id="分享与订阅" tabindex="-1">分享与订阅 <a class="header-anchor" href="#分享与订阅" aria-label="Permalink to &quot;分享与订阅&quot;">​</a></h2><ul><li>点击入站 → <strong>分享</strong>（电脑上也可以直接点行内的“分享”按钮）：显示通用分享链接和二维码；Snell 没有通用链接，显示 Surge 配置行。Surge 用户请使用 Surge 订阅</li><li><strong>订阅</strong> 页：一个链接包含落地和中转线路，可以建多个、分别过滤和改名，也可以分享给别人，见 <a href="./subscription">订阅</a></li></ul><table tabindex="0"><thead><tr><th>订阅格式</th><th>适用客户端</th><th>不包含</th></tr></thead><tbody><tr><td>自动识别</td><td>按客户端 UA 返回对应格式</td><td></td></tr><tr><td>Clash / Mihomo</td><td>Clash Verge、Stash、FlClash</td><td>XHTTP、Snell、NaïveProxy</td></tr><tr><td>sing-box</td><td>SFA / SFI / SFM</td><td>XHTTP、Snell</td></tr><tr><td>Shadowrocket</td><td>Shadowrocket</td><td>XHTTP、Snell、NaïveProxy</td></tr><tr><td>Loon</td><td>Loon</td><td>TUIC、gRPC、XHTTP、Snell、NaïveProxy</td></tr><tr><td>Quantumult X</td><td>Quantumult X</td><td>Hysteria2、TUIC、gRPC、XHTTP、ShadowTLS、Snell、NaïveProxy</td></tr><tr><td>通用 base64</td><td>v2rayN、NekoBox</td><td>Snell</td></tr><tr><td>Surge</td><td>Surge</td><td>VLESS、Reality、gRPC、XHTTP、NaïveProxy</td></tr></tbody></table><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>入站多了不好管理时，点列表上方的 <strong>多选</strong>：点卡片勾选，<strong>全选</strong> 会选中当前列表里显示的全部入站（可以先用搜索或节点筛选缩小范围），然后可以批量 <strong>启用</strong>、<strong>停用</strong> 或 <strong>删除</strong>。每个受影响的内核只下发一次配置。</p><h2 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to &quot;备份&quot;">​</a></h2><p>在 <strong>网站配置 → 数据备份与恢复</strong> 里勾选 <strong>内核与入站</strong>，会导出节点上的内核、所有入站（包括导入的节点）、中转线路和流量统计基准。所有订阅（包括分享出去的）也包含在内。恢复后面板会把内核配置重新推到在线的节点，离线的节点重连时自动补上。3.0.9 之前导出的备份不包含这部分，升级后请重新导出一次。</p><p>下一步：<a href="./relay">对接中转</a></p>',39)])])}const c=d(o,[["render",l]]);export{u as __pageData,c as default};
